import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Влияние гильдий","description":"","frontmatter":{"pageId":"players/guild-influence","contentRevision":5},"headers":[],"relativePath":"ru/players/guild-influence.md","filePath":"ru/players/guild-influence.md"}'),t={name:"ru/players/guild-influence.md"};function n(o,e,s,u,c,d){return l(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="влияние-гильдии" tabindex="-1">Влияние гильдий <a class="header-anchor" href="#влияние-гильдии" aria-label="Permalink to &quot;Влияние гильдий&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Открой <strong>Зоны влияния гильдий → Настройки</strong> на мировой карте или настройки влияния в союзе. Выбери домашнюю поверхностную колонию и явно опубликуй влияние. Это раскрывает название союза и цвет, но не казну, состав и чат. По умолчанию публикации нет.</p><p>Радиус — 3 соседних шага по суше, сила 4 − расстояние. Вода останавливает распространение. У одного союза берётся максимум, не сумма; равная сила разных союзов даёт нейтральную штриховку. Владелец союза выбирает один из 16 цветов. Офлайн-источники учитываются.</p><p>Локальный переключатель слоя не отзывает согласие. Для отзыва используй отдельную кнопку: версия согласия меняется даже при уже выключенной публикации, блокируя запоздавший запрос включения.</p><h2 id="publish-influence" tabindex="-1">Опубликовать, скрыть слой или отозвать согласие? <a class="header-anchor" href="#publish-influence" aria-label="Permalink to &quot;Опубликовать, скрыть слой или отозвать согласие? {#publish-influence}&quot;">​</a></h2><ol><li>Вступи в альянс и используй подходящую домашнюю root-surface колонию.</li><li>На карте мира открой настройки зон влияния. Проверь контекст поселения/альянса и явно включи публикацию; по умолчанию её нет.</li><li>Проверь источник и цвет на карте. Радиус — три сухопутных шага, не простой круг через море. У одного альянса берётся максимум силы, равенство разных даёт нейтральную штриховку.</li><li>Локальная кнопка слоя убирает только картинку у тебя. Чтобы перестать публиковать, используй <strong>отзыв согласия</strong>. Он повышает версию даже при выключенном источнике, защищая от запоздавшего enable.</li></ol><p>Цвет меняет владелец альянса из 16 вариантов. Offline не убирает источник. Никаких прав на землю, ресурсов за цвет, войны гильдий или аванпостов эта механика не создаёт.</p><h2 id="influence-refusal" tabindex="-1">Почему источник не включается или слой недоступен? <a class="header-anchor" href="#influence-refusal" aria-label="Permalink to &quot;Почему источник не включается или слой недоступен? {#influence-refusal}&quot;">​</a></h2><p>Сверь членство, актуальное поселение, root-surface и текущую жизнь колонии. Reset/выход/роспуск отзывают согласие; после archive restore проверяются контекст и свободная ёмкость. Старое ожидающее включение не должно применяться к новой колонии.</p><p>Лимит сервера — 128 активных источников. Если импортированная база уже превышает его, недоступен весь слой, а не случайно выбранные источники. Обнови состояние и сообщи администратору; он может выключить источник, но не включить его за игрока. Отсутствие цвета не означает потерю поселения.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Это не владение, войны, аванпосты или право доступа. Максимум 128 активных источников на весь сервер. При превышении импортированной БД слой целиком недоступен. Reset/выход/роспуск отзывают согласие; восстановление архива перепроверяет контекст и вместимость. Администратор может выключить, но не включить за игрока.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./community">Профили, друзья и союзы</a></li><li><a href="./world">Общая планета и поселения</a></li><li><a href="./../admins/api">Справочник REST API</a></li></ul>',16)])])}const f=a(t,[["render",n]]);export{p as __pageData,f as default};
